// Package legacyoracle keeps, for tests, what the removed legacy capture
// write path stored.
//
// The legacy write path (one writer operation per stage start, header group,
// body chunk and stage end) was the reference the unified write path was
// proved against: session-level tests ran the same traffic through both and
// compared the stored rows. Before the legacy session code was removed, each
// such test froze the legacy side as a golden file, generated by the legacy
// session at commit ce4e976 (the oracle commit's non-test code is that
// commit's). The tests now compare the unified path against those files.
//
// A file is testdata/legacy-oracle/<test name>.json in the test's package
// directory (gzip-compressed as .json.gz above 1 MiB) and holds named
// values, one per line. Every value is normalised by the test
// that froze it so that a rerun produces the same bytes: audit ids come from
// a seeded source or are left out, times come from a counter clock or are
// left out, and ciphertext is replaced by the length and SHA-256 of what it
// opens to under its own row's AAD, never kept as such. The test's comment
// says which.
//
// The files cannot be regenerated: the code that produced them is gone.
package legacyoracle

import (
	"bytes"
	"compress/gzip"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"testing"
	"unicode/utf8"
)

// WriteEnv, when set to a non-empty value, makes Value record the legacy
// side instead of checking it. Only the oracle commit, which still had the
// legacy path, could do that.
const WriteEnv = "LLMAPI_WRITE_LEGACY_ORACLE"

// Source is recorded in every file.
const Source = "legacy capture write path at commit ce4e976"

type file struct {
	path    string
	values  map[string]json.RawMessage
	loaded  bool
	written bool
}

var (
	filesMu sync.Mutex
	files   = map[string]*file{}
)

// Value returns the frozen value name of the running test. When legacy is
// not nil it is the legacy side computed now: it is checked against the file,
// or recorded when WriteEnv is set.
func Value[T any](t testing.TB, name string, legacy *T) T {
	t.Helper()
	filesMu.Lock()
	defer filesMu.Unlock()
	entry := files[t.Name()]
	if entry == nil {
		entry = &file{path: Path(t.Name()), values: map[string]json.RawMessage{}}
		files[t.Name()] = entry
	}
	if os.Getenv(WriteEnv) != "" {
		if legacy == nil {
			t.Fatalf("legacy oracle %s: %s needs the legacy side to record", entry.path, name)
		}
		encoded, err := canonical(legacy)
		if err != nil {
			t.Fatalf("legacy oracle %s: encode %s: %v", entry.path, name, err)
		}
		if _, seen := entry.values[name]; seen {
			t.Fatalf("legacy oracle %s: %s recorded twice", entry.path, name)
		}
		entry.values[name] = encoded
		if !entry.written {
			entry.written = true
			t.Cleanup(func() {
				if t.Failed() {
					return
				}
				filesMu.Lock()
				defer filesMu.Unlock()
				if err := entry.write(); err != nil {
					t.Errorf("legacy oracle %s: %v", entry.path, err)
				}
			})
		}
		return *legacy
	}
	if !entry.loaded {
		if err := entry.read(); err != nil {
			t.Fatalf("legacy oracle %s: %v", entry.path, err)
		}
		entry.loaded = true
	}
	raw, ok := entry.values[name]
	if !ok {
		t.Fatalf("legacy oracle %s has no value %q", entry.path, name)
	}
	var frozen T
	if err := Decode(raw, &frozen); err != nil {
		t.Fatalf("legacy oracle %s: decode %s: %v", entry.path, name, err)
	}
	if legacy != nil {
		want, _ := canonical(&frozen)
		got, err := canonical(legacy)
		if err != nil {
			t.Fatalf("legacy oracle %s: encode %s: %v", entry.path, name, err)
		}
		if !bytes.Equal(want, got) {
			t.Fatalf("legacy oracle %s: %s differs from the frozen value:\n%s", entry.path, name, firstDifference(want, got))
		}
	}
	return frozen
}

// Path is the file of a test.
func Path(testName string) string {
	var builder strings.Builder
	for _, value := range testName {
		switch {
		case value == '/':
			builder.WriteString("__")
		case value >= 'a' && value <= 'z', value >= 'A' && value <= 'Z', value >= '0' && value <= '9', value == '-', value == '.':
			builder.WriteRune(value)
		default:
			builder.WriteRune('_')
		}
	}
	return filepath.Join("testdata", "legacy-oracle", builder.String()+".json")
}

type document struct {
	Source string                     `json:"source"`
	Values map[string]json.RawMessage `json:"values"`
}

func (entry *file) read() error {
	content, err := os.ReadFile(entry.path)
	if errors.Is(err, fs.ErrNotExist) {
		compressed, gzErr := os.ReadFile(entry.path + ".gz")
		if errors.Is(gzErr, fs.ErrNotExist) {
			return errors.New("missing; it was generated with the legacy write path, which no longer exists")
		}
		if gzErr != nil {
			return gzErr
		}
		reader, gzErr := gzip.NewReader(bytes.NewReader(compressed))
		if gzErr != nil {
			return gzErr
		}
		content, err = io.ReadAll(reader)
	}
	if err != nil {
		return err
	}
	var parsed document
	if err := json.Unmarshal(bytes.ReplaceAll(content, []byte("\r\n"), []byte("\n")), &parsed); err != nil {
		return err
	}
	entry.values = parsed.Values
	return nil
}

// write stores one value per line, in name order.
func (entry *file) write() error {
	names := make([]string, 0, len(entry.values))
	for name := range entry.values {
		names = append(names, name)
	}
	sort.Strings(names)
	var buffer bytes.Buffer
	source, _ := json.Marshal(Source)
	buffer.WriteString("{\"source\": " + string(source) + ",\n\"values\": {\n")
	for index, name := range names {
		key, _ := json.Marshal(name)
		buffer.Write(key)
		buffer.WriteString(": ")
		buffer.Write(entry.values[name])
		if index < len(names)-1 {
			buffer.WriteString(",")
		}
		buffer.WriteString("\n")
	}
	buffer.WriteString("}}\n")
	if err := os.MkdirAll(filepath.Dir(entry.path), 0o755); err != nil {
		return err
	}
	if buffer.Len() <= compressAbove {
		return os.WriteFile(entry.path, buffer.Bytes(), 0o644)
	}
	var compressed bytes.Buffer
	writer, err := gzip.NewWriterLevel(&compressed, gzip.BestCompression)
	if err != nil {
		return err
	}
	if _, err := writer.Write(buffer.Bytes()); err != nil {
		return err
	}
	if err := writer.Close(); err != nil {
		return err
	}
	return os.WriteFile(entry.path+".gz", compressed.Bytes(), 0o644)
}

// compressAbove is the size from which a file is stored gzip-compressed, as
// <name>.json.gz; `gzip -dc` shows the same text.
const compressAbove = 1 << 20

// canonical encodes a value with sorted map keys and no HTML escaping.
func canonical(value any) ([]byte, error) {
	var buffer bytes.Buffer
	encoder := json.NewEncoder(&buffer)
	encoder.SetEscapeHTML(false)
	if err := encoder.Encode(value); err != nil {
		return nil, err
	}
	// Round-trip through a generic value so that struct and map encodings of
	// the same data compare equal.
	// Numbers stay exact: nanosecond times exceed a float64's integers.
	var generic any
	decoder := json.NewDecoder(bytes.NewReader(buffer.Bytes()))
	decoder.UseNumber()
	if err := decoder.Decode(&generic); err != nil {
		return nil, err
	}
	buffer.Reset()
	if err := encoder.Encode(generic); err != nil {
		return nil, err
	}
	return bytes.TrimSpace(buffer.Bytes()), nil
}

// Decode decodes JSON as Value does: numbers in untyped values stay
// json.Number, so they are exact.
func Decode(data []byte, into any) error {
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.UseNumber()
	return decoder.Decode(into)
}

// RoundTrip returns value as Value would return it after freezing it, so
// that an untyped value computed now compares with a frozen one.
func RoundTrip[T any](value T) (T, error) {
	var out T
	encoded, err := json.Marshal(value)
	if err != nil {
		return out, err
	}
	err = Decode(encoded, &out)
	return out, err
}

// Digest keeps a long text as its length, SHA-256 and first bytes, so that a
// frozen view of a large export stays small and a difference still shows
// where it starts.
func Digest(text string) string {
	const keep = 1500
	if len(text) <= 2*keep {
		return text
	}
	cut := keep
	for cut > 0 && !utf8.RuneStart(text[cut]) {
		cut--
	}
	sum := sha256.Sum256([]byte(text))
	return fmt.Sprintf("%s…[len=%d sha256=%s]", strings.ToValidUTF8(text[:cut], "?"), len(text), hex.EncodeToString(sum[:]))
}

func firstDifference(want, got []byte) string {
	at := 0
	for at < len(want) && at < len(got) && want[at] == got[at] {
		at++
	}
	from := max(at-200, 0)
	return "frozen " + string(want[from:min(len(want), at+300)]) + "\nnow    " + string(got[from:min(len(got), at+300)])
}
